const OPEN_BRACKETS = /[<\uFF1C\uFE64\u2329\u3008\u27E8]|&(?:lt|#0*60|#x0*3c);?/gi;
const CLOSE_BRACKETS = /[>\uFF1E\uFE65\u232A\u3009\u27E9]|&(?:gt|#0*62|#x0*3e);?/gi;

