  assert.deepEqual(parseControlId(controlId('sleep', 'devin-abc123')), { action: 'sleep', taskId: 'devin-abc123' });
  for (const bad of ['devin:delete:devin-1', 'devin:stop:', 'devin:stop:a b', 'other:stop:devin-1', 'devin:stop:x:y']) {
